pub use crate::review::SuggestedFix;
use serde::{Deserialize, Serialize};
use std::path::PathBuf;

/// Complete diagnostic report generated by the Topological Root-Cause Detective.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct DiagnosisReport {
    /// Unique report identifier.
    pub id: String,
    /// ISO-8601 creation timestamp.
    pub timestamp: String,
    /// Extracted crash type (e.g. "AttributeError", "NullPointerException", "panic").
    pub crash_type: String,
    /// Extracted crash message / reason.
    pub crash_message: String,
    /// Primary failing file path identified in stack trace.
    pub failing_file: String,
    /// Primary failing line number in stack trace.
    pub failing_line: usize,
    /// Categorized fault archetype.
    pub fault_category: FaultCategory,
    /// The highest-confidence root-cause candidate.
    pub root_cause_candidate: Option<FaultCandidate>,
    /// All evaluated frames ranked by suspicion score.
    pub candidates: Vec<FaultCandidate>,
    /// Normalized call path frames from the traceback.
    pub call_path: Vec<TracebackFrame>,
    /// Backward variable def-use provenance slice (if identified).
    pub provenance: Option<ProvenanceSlice>,
    /// Recommended code patch to remediate the defect.
    pub suggested_fix: Option<SuggestedFix>,
    /// Framework-native regression test reproducer.
    pub regression_test: Option<RegressionTestReproducer>,
    /// Diagnostic verdict / confidence classification.
    pub verdict: DiagnosisVerdict,
    /// Engine execution mode used (offline vs AI).
    pub execution_mode: DiagnosticExecutionMode,
    /// Execution duration in milliseconds.
    pub execution_duration_ms: u64,
}

/// A single normalized stack frame from a parsed traceback.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct TracebackFrame {
    /// 0-indexed position in call path (0 = root/entrypoint, N = leaf panic site).
    pub frame_index: usize,
    /// Normalized repository-relative file path.
    pub file_path: PathBuf,
    /// 1-indexed source line number.
    pub line_number: usize,
    /// 1-indexed column number if available.
    pub column: Option<usize>,
    /// Function or method symbol name.
    pub function_name: String,
    /// Extracted source code snippet around the line.
    pub code_snippet: Option<String>,
    /// True if the frame belongs to repository source code (not stdlib/vendor).
    pub is_in_project: bool,
    /// True if this frame represents the leaf panic or exception site.
    pub is_leaf_panic: bool,
    /// Canonical URI / ID in the cartograph graph database if anchored.
    pub ast_symbol_id: Option<String>,
    /// Tree-sitter AST node kind (e.g. "function_definition", "method_declaration").
    pub ast_node_kind: Option<String>,
    /// Programming language of the source file.
    pub language: String,
}

/// Evaluated candidate in the topological fault localization ranking.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct FaultCandidate {
    /// Frame index corresponding to `call_path`.
    pub frame_index: usize,
    /// Target file path.
    pub file_path: PathBuf,
    /// Target line number.
    pub line_number: usize,
    /// Enclosing function or symbol name.
    pub function_name: String,
    /// Assigned topological role in the failure cascade.
    pub role: FaultRole,
    /// Mathematical suspicion score between 0.0 (innocent) and 1.0 (certain root cause).
    pub suspicion_score: f64,
    /// Human-readable explanation of why this frame was scored.
    pub reason: String,
    /// Commit recency in days via git blame if available.
    pub blame_recency_days: Option<u64>,
    /// Cognitive complexity of the enclosing function if calculated.
    pub cognitive_complexity: Option<u32>,
    /// True if this frame crosses an architectural package/layer boundary.
    pub is_boundary_crossing: bool,
    /// Tainted variable identifier tracked through this frame.
    pub variable_taint: Option<String>,
}

/// Architectural role of a frame in the crash cascade.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum FaultRole {
    /// The origin site where invalid state, null, or corrupted data was introduced.
    RootCause,
    /// Intermediate caller that propagated invalid state without validating.
    Propagator,
    /// The leaf site where the runtime exception or panic occurred.
    PanicSite,
    /// Upstream caller that cleanly initiated standard execution.
    InnocentCaller,
}

impl std::fmt::Display for FaultRole {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            FaultRole::RootCause => write!(f, "RootCause"),
            FaultRole::Propagator => write!(f, "Propagator"),
            FaultRole::PanicSite => write!(f, "PanicSite"),
            FaultRole::InnocentCaller => write!(f, "InnocentCaller"),
        }
    }
}

/// Standardized archetype of software fault.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum FaultCategory {
    /// Null/None/Nil pointer or attribute dereference.
    NullDeref,
    /// Index out of bounds or slice range violation.
    OutOfBounds,
    /// Type mismatch, unexpected shape, or unhandled enum variant.
    TypeDrift,
    /// Missing validation guard or precondition check.
    MissingGuard,
    /// Business rule or state machine invariant breach.
    StateInvariantViolation,
    /// Unclosed connection, file descriptor, or memory leak.
    ResourceLeak,
    /// Race condition, deadlock, or channel panic.
    ConcurrencyPanic,
    /// Unclassified or generic runtime exception.
    Unknown,
}

impl std::fmt::Display for FaultCategory {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            FaultCategory::NullDeref => write!(f, "NullDeref"),
            FaultCategory::OutOfBounds => write!(f, "OutOfBounds"),
            FaultCategory::TypeDrift => write!(f, "TypeDrift"),
            FaultCategory::MissingGuard => write!(f, "MissingGuard"),
            FaultCategory::StateInvariantViolation => write!(f, "StateInvariantViolation"),
            FaultCategory::ResourceLeak => write!(f, "ResourceLeak"),
            FaultCategory::ConcurrencyPanic => write!(f, "ConcurrencyPanic"),
            FaultCategory::Unknown => write!(f, "Unknown"),
        }
    }
}

/// Backward variable def-use provenance tracking chain.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProvenanceSlice {
    /// Variable name traced.
    pub variable_name: String,
    /// File path where the variable was assigned or returned.
    pub origin_file: PathBuf,
    /// Line number where the variable was assigned or returned.
    pub origin_line: usize,
    /// Source expression that produced the value (e.g. `repo.find_by_id(id)`).
    pub origin_expression: String,
    /// Ordered steps from origin down to panic site.
    pub propagation_steps: Vec<ProvenanceStep>,
}

/// A single hop in variable provenance propagation.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProvenanceStep {
    pub step_index: usize,
    pub file_path: PathBuf,
    pub line_number: usize,
    pub expression: String,
    pub description: String,
}

/// Framework-native unit test reproducer scaffolding.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RegressionTestReproducer {
    /// Destination test file path.
    pub target_file: PathBuf,
    /// Test framework name (e.g. "pytest", "cargo_test", "jest_vitest", "go_test").
    pub framework: String,
    /// Generated test function name.
    pub test_name: String,
    /// Executable source code for the test reproducer.
    pub test_code: String,
}

/// Confidence classification of the diagnosis.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum DiagnosisVerdict {
    /// Root cause pinpointed with high mathematical confidence (> 0.80).
    DefiniteRootCause,
    /// Probable root cause identified (0.50 - 0.80).
    ProbableRootCause,
    /// Insufficient graph evidence; manual inspection required (< 0.50).
    Inconclusive,
}

/// Execution mode used by the diagnosis engine.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum DiagnosticExecutionMode {
    OfflineDeterministic,
    AiAugmented { provider: String, model: String },
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_diagnosis_report_serialization() {
        let report = DiagnosisReport {
            id: "diag-123".to_string(),
            timestamp: "2026-10-01T12:00:00Z".to_string(),
            crash_type: "AttributeError".to_string(),
            crash_message: "'NoneType' object has no attribute 'id'".to_string(),
            failing_file: "src/services/order.py".to_string(),
            failing_line: 42,
            fault_category: FaultCategory::NullDeref,
            root_cause_candidate: Some(FaultCandidate {
                frame_index: 1,
                file_path: PathBuf::from("src/services/repo.py"),
                line_number: 18,
                function_name: "get_user".to_string(),
                role: FaultRole::RootCause,
                suspicion_score: 0.92,
                reason: "Returned None without checking existence".to_string(),
                blame_recency_days: Some(3),
                cognitive_complexity: Some(8),
                is_boundary_crossing: true,
                variable_taint: Some("user".to_string()),
            }),
            candidates: vec![],
            call_path: vec![TracebackFrame {
                frame_index: 0,
                file_path: PathBuf::from("src/main.py"),
                line_number: 10,
                column: Some(4),
                function_name: "main".to_string(),
                code_snippet: Some("order = process()".to_string()),
                is_in_project: true,
                is_leaf_panic: false,
                ast_symbol_id: Some("cartograph://src/main.py::::main#function".to_string()),
                ast_node_kind: Some("function_definition".to_string()),
                language: "python".to_string(),
            }],
            provenance: Some(ProvenanceSlice {
                variable_name: "user".to_string(),
                origin_file: PathBuf::from("src/services/repo.py"),
                origin_line: 18,
                origin_expression: "db.query()".to_string(),
                propagation_steps: vec![],
            }),
            suggested_fix: Some(SuggestedFix {
                replacement_code: "if user is None: return None".to_string(),
                unified_diff_patch: "--- a/src/services/repo.py\n+++ b/src/services/repo.py\n"
                    .to_string(),
                explanation: "Guard against null user".to_string(),
            }),
            regression_test: Some(RegressionTestReproducer {
                target_file: PathBuf::from("tests/test_order_regression.py"),
                framework: "pytest".to_string(),
                test_name: "test_regression_order_none_user".to_string(),
                test_code: "def test_regression_order_none_user(): pass".to_string(),
            }),
            verdict: DiagnosisVerdict::DefiniteRootCause,
            execution_mode: DiagnosticExecutionMode::OfflineDeterministic,
            execution_duration_ms: 12,
        };

        let json = serde_json::to_string(&report).expect("Serialization failed");
        let deserialized: DiagnosisReport =
            serde_json::from_str(&json).expect("Deserialization failed");
        assert_eq!(report.id, deserialized.id);
        assert_eq!(report.fault_category, FaultCategory::NullDeref);
        assert_eq!(report.verdict, DiagnosisVerdict::DefiniteRootCause);
    }
}
